let datos = msg.payload;

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        node.warn("El mensaje recibido no es un JSON válido");
        return null;
    }
}

if (!datos || typeof datos !== "object") {
    return null;
}

let id = datos.id_conductor;
let fc = Number(datos.frecuencia_cardiaca);
let spo2 = Number(datos.spo2);

if (!id) {
    node.warn("Mensaje sin id_conductor");
    return null;
}

if (!Number.isFinite(fc) || !Number.isFinite(spo2)) {
    return null;
}

const UMBRALES_DEFECTO = {
    fc_min_normal: 60,
    fc_max_normal: 100,
    spo2_min_normal: 90,
    spo2_prealerta_min: 85,
    spo2_prealerta_max: 89,
    fc_caida_prealerta: 5,
    fc_critica: 60,
    spo2_critica: 80,
    lecturas_criticas: 3
};
let u = Object.assign({}, UMBRALES_DEFECTO, (flow.get("umbrales_conductor") || {})[id]);


let spo2Valido = msg.spo2_valido !== false;


if (!spo2Valido) {
    node.status({
        fill: "blue",
        shape: "ring",
        text: id + " - Movimiento, SpO2 no medible"
    });
    return null;
}

let conductores = flow.get("conductores") || {};

if (!conductores[id]) {
    conductores[id] = {
        historialFC: [],
        criticasConsecutivas: 0
    };
}

let conductor = conductores[id];
let historial = conductor.historialFC;

let promedio = fc;

if (historial.length > 0) {
    promedio =
        historial.reduce((suma, valor) => suma + valor, 0)
        / historial.length;
}

let tendenciaBaja = false;

if (historial.length >= 3) {
    tendenciaBaja = (promedio - fc) > u.fc_caida_prealerta;
}

let spo2Critica = spo2 <= u.spo2_critica;
let spo2PreAlerta = spo2 >= u.spo2_prealerta_min && spo2 <= u.spo2_prealerta_max;
let spo2Normal = spo2 >= u.spo2_min_normal;

let critica = fc <= u.fc_critica || spo2Critica;

if (critica) {
    conductor.criticasConsecutivas++;
} else {
    conductor.criticasConsecutivas = 0;
}

let accion;
let estado;

if (conductor.criticasConsecutivas >= u.lecturas_criticas) {
    estado = "ALERTA CRITICA";
    accion = "Prender led rojo";
} else if (critica || tendenciaBaja || spo2PreAlerta) {
    estado = "PRE-ALERTA";
    accion = "Prender led amarillo";
} else if (fc >= u.fc_min_normal && fc <= u.fc_max_normal && spo2Normal) {
    estado = "NORMAL";
    accion = "Prender led verde";
} else {
    estado = "PRE-ALERTA";
    accion = "Prender led amarillo";
}

historial.push(fc);

if (historial.length > 3) {
    historial.shift();
}

conductor.historialFC = historial;
conductores[id] = conductor;

flow.set("conductores", conductores);

msg.topic = "sergio.vnsquez@uao.edu.co/tp01/command/" + id;
msg.payload = accion;

msg.id_conductor = id;
msg.estado = estado;
msg.frecuencia_cardiaca = fc;
msg.spo2 = spo2;
msg.spo2_valido = spo2Valido;
msg.promedio_fc = promedio;
msg.criticas_consecutivas = conductor.criticasConsecutivas;
msg.umbrales = u;

node.status({
    fill: estado === "NORMAL" ? "green" :
          estado === "PRE-ALERTA" ? "yellow" : "red",
    shape: "dot",
    text: id + " - " + estado
});

return msg;

const CAMPOS = [
    "fc_min_normal", "fc_max_normal", "spo2_min_normal",
    "spo2_prealerta_min", "spo2_prealerta_max",
    "fc_caida_prealerta", "fc_critica", "spo2_critica", "lecturas_criticas"
];

const docs = Array.isArray(msg.payload) ? msg.payload : [];
const umbrales = {};
let invalidos = 0;

for (const doc of docs) {
    if (!doc || !doc.id_conductor) continue;
    const u = {};
    let ok = true;
    for (const campo of CAMPOS) {
        const v = Number(doc[campo]);
        if (!Number.isFinite(v)) { ok = false; break; }
        u[campo] = v;
    }
    if (ok) {
        ok = u.fc_min_normal < u.fc_max_normal
            && u.spo2_critica < u.spo2_prealerta_min
            && u.spo2_prealerta_min <= u.spo2_prealerta_max
            && u.spo2_prealerta_max < u.spo2_min_normal
            && u.lecturas_criticas >= 1;
    }
    if (!ok) {
        invalidos++;
        node.warn("Umbrales inválidos para " + doc.id_conductor + "; se usan los valores por defecto");
        continue;
    }
    umbrales[String(doc.id_conductor).trim()] = u;
}

flow.set("umbrales_conductor", umbrales);

node.status({
    fill: invalidos ? "yellow" : "green",
    shape: "dot",
    text: Object.keys(umbrales).length + " conductores" + (invalidos ? ", " + invalidos + " inválidos" : "") +
        " · " + new Date().toLocaleTimeString("es-CO", { timeZone: "America/Bogota", hour12: false })
});

return null;

let datos = msg.payload;

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        node.warn("El mensaje recibido no es un JSON válido");
        return null;
    }
}

if (!datos || typeof datos !== "object") {
    return null;
}

let id = datos.id_conductor;

if (!id) {
    node.warn("Mensaje sin id_conductor");
    return null;
}

let tiempoMsg = Date.parse(datos.marca_tiempo);
if (!Number.isFinite(tiempoMsg)) {
    tiempoMsg = Date.now();
}

const VENTANA_NORMAL_MS = 10000;
const VENTANA_FATIGA_MS = 5000;
const RETENCION_MS = 20000;
const INTERVALO_ALERTA_MS = 5000;  

let estados = flow.get("validacion_movimiento") || {};

if (!estados[id]) {
    estados[id] = {
        movimientos: [],
        ventanaMs: VENTANA_NORMAL_MS,
        fcAnterior: null,
        ultimaAlertaMs: 0
    };
}

let e = estados[id];


if (Number(datos.movimiento) === 1) {
    e.movimientos.push(tiempoMsg);
    e.movimientos = e.movimientos.filter(t => (tiempoMsg - t) <= RETENCION_MS);

    let alerta = null;

    if ((tiempoMsg - (e.ultimaAlertaMs || 0)) >= INTERVALO_ALERTA_MS) {
        e.ultimaAlertaMs = tiempoMsg;

        alerta = {
            topic: "sergio.vnsquez@uao.edu.co/tp01/alerta/" + id,
            payload: "ALERTA: el conductor se está moviendo, no se puede tomar el dato de SpO2",
            id_conductor: id,
            hubo_movimiento: true,
            spo2_valido: false
        };

        node.status({
            fill: "blue",
            shape: "ring",
            text: id + " - Movimiento, SpO2 no medible"
        });
    }

    estados[id] = e;
    flow.set("validacion_movimiento", estados);

    return [null, alerta];   
}


let fc = Number(datos.frecuencia_cardiaca);
let spo2 = Number(datos.spo2);

if (!Number.isFinite(fc) || !Number.isFinite(spo2)) {
    return null;
}

let ventana = e.ventanaMs;

let huboMovimiento = e.movimientos.some(
    t => t >= (tiempoMsg - ventana) && t <= tiempoMsg
);

if (e.fcAnterior !== null && (e.fcAnterior - fc) >= 5) {
    e.ventanaMs = VENTANA_FATIGA_MS;
} else {
    e.ventanaMs = VENTANA_NORMAL_MS;
}
e.fcAnterior = fc;

e.movimientos = e.movimientos.filter(t => (tiempoMsg - t) <= RETENCION_MS);

estados[id] = e;
flow.set("validacion_movimiento", estados);

msg.payload = datos;
msg.spo2_valido = !huboMovimiento;
msg.hubo_movimiento = huboMovimiento;
msg.ventana_ms = ventana;

node.status({
    fill: huboMovimiento ? "red" : "green",
    shape: "dot",
    text: id + (huboMovimiento ? " - SpO2 inválida" : " - SpO2 válida")
});

return [msg, null];

let datos = msg.payload;

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        return [null, null];
    }
}

if (!datos || typeof datos !== "object" || !datos.id_conductor) {
    return [null, null];
}

let ahora = new Date();

if (Number(datos.movimiento) === 1) {
    return [
        null,
        {
            payload: {
                id_conductor: datos.id_conductor,
                marca_tiempo: datos.marca_tiempo || ahora.toISOString(),
                movimiento: 1,
                timestamp_servidor: ahora
            }
        }
    ];
}

let fc = Number(datos.frecuencia_cardiaca);
let spo2 = Number(datos.spo2);

if (!Number.isFinite(fc) || !Number.isFinite(spo2)) {
    return [null, null];
}

return [
    {
        payload: {
            id_conductor: datos.id_conductor,
            marca_tiempo: datos.marca_tiempo,
            frecuencia_cardiaca: fc,
            spo2: spo2,
            timestamp_servidor: ahora
        }
    },
    null
];

let id = msg.id_conductor;
let estado = msg.estado;
let accion = msg.payload;

if (!id || !estado) {
    return [null, null, null];
}

let ahora = new Date();

let estadoMsg = {
    payload: {
        id_conductor: id,
        estado: estado,
        accion: accion,
        promedio_fc: Number(msg.promedio_fc),
        criticas_consecutivas: Number(msg.criticas_consecutivas),
        timestamp: ahora
    }
};

let alertasActivas = flow.get("alertas_activas_mongo") || {};
let activaAnterior = alertasActivas[id] || null;

let alertaInsert = null;
let alertaCerrar = null;

if (activaAnterior && activaAnterior.estado !== estado) {
    alertaCerrar = {
        query: {
            _id: activaAnterior._id
        },
        payload: {
            $set: {
                timestamp_fin: ahora,
                activa: false
            }
        }
    };

    delete alertasActivas[id];
    activaAnterior = null;
}

if (estado !== "NORMAL" && !activaAnterior) {
    let alertaId =
        id + "-" +
        Date.now().toString() + "-" +
        Math.random().toString(16).slice(2, 8);

    let tipoAlerta;
    let nivel;
    let descripcion;

    if (estado === "ALERTA CRITICA") {
        tipoAlerta = "ALERTA_CRITICA";
        nivel = "CRITICO";
        descripcion =
            "Alerta critica detectada: FC=" +
            Number(msg.frecuencia_cardiaca).toFixed(1) +
            " bpm, SpO2=" +
            Number(msg.spo2).toFixed(1) +
            "%, lecturas criticas consecutivas=" +
            Number(msg.criticas_consecutivas);
    } else {
        tipoAlerta = "PRE_ALERTA";
        nivel = "MEDIO";
        descripcion =
            "Pre-alerta detectada: FC=" +
            Number(msg.frecuencia_cardiaca).toFixed(1) +
            " bpm, SpO2=" +
            Number(msg.spo2).toFixed(1) +
            "%, promedio FC=" +
            Number(msg.promedio_fc).toFixed(1) +
            " bpm";
    }

    alertaInsert = {
        payload: {
            _id: alertaId,
            id_conductor: id,
            tipo_alerta: tipoAlerta,
            descripcion: descripcion,
            nivel: nivel,
            timestamp_inicio: ahora,
            timestamp_fin: null,
            activa: true
        }
    };

    alertasActivas[id] = {
        _id: alertaId,
        estado: estado
    };
}

flow.set("alertas_activas_mongo", alertasActivas);

return [
    estadoMsg,
    alertaInsert,
    alertaCerrar
];

const datos = Array.isArray(msg.payload) ? msg.payload : [];
const num = x => x !== null && x !== undefined && String(x).trim() !== '' && isFinite(Number(x));
const limpios = [];
let descartados = 0;

for (const d of datos) {
  // incompletos
  if (!d || !d.id_conductor || String(d.id_conductor).trim() === '') { descartados++; continue; }
  if (!num(d.frecuencia_cardiaca) || !num(d.spo2)) { descartados++; continue; }

  // formato
  const fc = Number(d.frecuencia_cardiaca);
  const spo2 = Number(d.spo2);

  // rangos fisicos
  if (fc < 30 || fc > 220 || spo2 < 60 || spo2 > 100) { descartados++; continue; }

  // fecha
  let t = new Date(d.marca_tiempo).getTime();
  const ts = new Date(d.timestamp_servidor).getTime();
  if (isNaN(t) || (!isNaN(ts) && Math.abs(t - ts) > 300000)) t = ts;
  if (isNaN(t)) { descartados++; continue; }

  limpios.push({
    _id: d._id,
    id_conductor: String(d.id_conductor).trim().toUpperCase(),
    marca_tiempo: new Date(t),
    frecuencia_cardiaca: fc,
    spo2: spo2
  });
}

msg.payload = limpios;
msg.descartados = descartados;
return msg;

// eventos de movimiento por conductor
const eventos = {};
for (const e of flow.get('tmp_eventos_mov') || []) {
  if (!e || !e.id_conductor) continue;
  const t = new Date(e.marca_tiempo || e.timestamp_servidor).getTime();
  if (isNaN(t)) continue;
  const id = String(e.id_conductor).trim().toUpperCase();
  (eventos[id] = eventos[id] || []).push(t);
}

// ordenar por conductor y hora
msg.payload.sort((a, b) => a.id_conductor < b.id_conductor ? -1 : a.id_conductor > b.id_conductor ? 1 : a.marca_tiempo - b.marca_tiempo);

const vistos = new Set();
const salida = [];
let duplicados = 0;
let idAnt = null, fcAnt = null, ventana = 10000;

for (const d of msg.payload) {
  // duplicado 
  const t = d.marca_tiempo.getTime();
  const clave = d.id_conductor + '|' + t;
  if (vistos.has(clave)) { duplicados++; continue; }
  vistos.add(clave);

  // hubo movimiento
  if (d.id_conductor !== idAnt) { idAnt = d.id_conductor; fcAnt = null; ventana = 10000; }
  const tiempos = eventos[d.id_conductor] || [];
  d.hubo_movimiento = tiempos.some(x => x >= t - ventana && x <= t);
  ventana = (fcAnt !== null && fcAnt - d.frecuencia_cardiaca >= 5) ? 5000 : 10000;
  fcAnt = d.frecuencia_cardiaca;

  // upsert por _id 
  const id = d._id !== undefined ? d._id : clave;
  delete d._id;
  salida.push({ query: { _id: id }, payload: { $set: d } });
}

flow.set('tmp_eventos_mov', undefined);
node.status({ fill: 'green', shape: 'dot', text: salida.length + ' limpios, ' + (msg.descartados + duplicados) + ' descartados' });
return [salida];

const DIAS = 7;
const OFFSET = -5 * 3600 * 1000;
const DIA = 86400000;

const ahora = Date.now();
const medianoche = Math.floor((ahora + OFFSET) / DIA) * DIA - OFFSET;   
const desde = medianoche - (DIAS - 1) * DIA;

msg.cfg = { ahora: ahora, desde: desde, dias: DIAS, offset: OFFSET };
msg.payload = { marca_tiempo: { $gte: new Date(desde) } };              
return msg;

msg.limpios = msg.payload;
msg.payload = { timestamp: { $gte: new Date(msg.cfg.desde) } };
return msg;

msg.estadosRaw = msg.payload;
msg.payload = { timestamp_inicio: { $gte: new Date(msg.cfg.desde) } };
return msg;

const OFFSET = msg.cfg.offset;

function limpiarId(valor) {
    if (!valor) return "";
    return String(valor).trim().toUpperCase();
}

function fechaLocal(milisegundos) {
    const d = new Date(milisegundos + OFFSET);
    return {
        dia: d.toISOString().slice(0, 10),
        hora: d.getUTCHours(),
        dsem: (d.getUTCDay() + 6) % 7    
    };
}

// --- Lecturas (datos_limpios)
const lecturas = [];
const listaLimpios = Array.isArray(msg.limpios) ? msg.limpios : [];
for (let i = 0; i < listaLimpios.length; i++) {
    const d = listaLimpios[i];
    const id = limpiarId(d.id_conductor);
    const t = new Date(d.marca_tiempo).getTime();
    const fc = Number(d.frecuencia_cardiaca);
    const spo2 = Number(d.spo2);
    if (id === "" || isNaN(t) || !isFinite(fc) || !isFinite(spo2)) continue;
    lecturas.push({ id: id, t: t, fc: fc, spo2: spo2, movimiento: d.hubo_movimiento === true });
}

// --- Estados (normal / prealerta / critica)
const CLAVES = { "NORMAL": "normal", "PRE-ALERTA": "prealerta", "ALERTA CRITICA": "critica" };
const estados = [];
const listaEstados = Array.isArray(msg.estadosRaw) ? msg.estadosRaw : [];
for (let i = 0; i < listaEstados.length; i++) {
    const e = listaEstados[i];
    const t = new Date(e.timestamp).getTime();
    const clave = CLAVES[e.estado];
    if (!clave || isNaN(t)) continue;
    const f = fechaLocal(t);
    estados.push({ clave: clave, dia: f.dia, hora: f.hora });
}

// --- Alertas
const alertas = [];
const listaAlertas = Array.isArray(msg.payload) ? msg.payload : [];
for (let i = 0; i < listaAlertas.length; i++) {
    const a = listaAlertas[i];
    const t = new Date(a.timestamp_inicio).getTime();
    if (isNaN(t)) continue;
    const f = fechaLocal(t);
    alertas.push({
        id: limpiarId(a.id_conductor),
        critica: a.tipo_alerta === "ALERTA_CRITICA",
        dia: f.dia,
        hora: f.hora,
        dsem: f.dsem
    });
}

msg.lecturas = lecturas;
msg.estados = estados;
msg.alertas = alertas;
msg.filas = { diaHora: [], conductor: [], semana: [] };  
msg.payload = null;
return msg;

const OFFSET = msg.cfg.offset;
const DIA = 86400000;
const NOMBRES = ["Lun", "Mar", "Mie", "Jue", "Vie", "Sab", "Dom"];

for (let i = 0; i < msg.cfg.dias; i++) {
    const fecha = new Date(msg.cfg.desde + i * DIA + OFFSET);
    const dia = fecha.toISOString().slice(0, 10);
    const dsem = (fecha.getUTCDay() + 6) % 7;      

    for (let hora = 0; hora < 24; hora++) {

        // contar estados de ese dia y hora
        let normal = 0, prealerta = 0, critica = 0;
        for (let j = 0; j < msg.estados.length; j++) {
            const e = msg.estados[j];
            if (e.dia !== dia || e.hora !== hora) continue;
            if (e.clave === "normal") normal++;
            if (e.clave === "prealerta") prealerta++;
            if (e.clave === "critica") critica++;
        }

        // contar alertas de ese dia y hora
        let totalAlertas = 0, alertasCriticas = 0;
        for (let j = 0; j < msg.alertas.length; j++) {
            const a = msg.alertas[j];
            if (a.dia !== dia || a.hora !== hora) continue;
            totalAlertas++;
            if (a.critica) alertasCriticas++;
        }

        msg.filas.diaHora.push({
            query: { _id: dia + "-" + hora },
            payload: { $set: {
                dia: dia,
                dsem: dsem,
                dia_semana: NOMBRES[dsem],
                hora: hora,
                normal: normal,
                prealerta: prealerta,
                critica: critica,
                alertas: totalAlertas,
                alertas_criticas: alertasCriticas,
                actualizado: new Date(msg.cfg.ahora)
            } }
        });
    }
}
return msg;

const GAP_S = 1800;       
const PAUSA_S = 120;      
const LIMITE_H = 6;       

function redondear(x) {
    return Math.round(x * 100) / 100;
}

function promedio(lista) {
    if (lista.length === 0) return null;
    let suma = 0;
    for (let i = 0; i < lista.length; i++) suma += lista[i];
    return redondear(suma / lista.length);
}


const porConductor = {};
for (let i = 0; i < msg.lecturas.length; i++) {
    const l = msg.lecturas[i];
    if (!porConductor[l.id]) porConductor[l.id] = [];
    porConductor[l.id].push(l);
}


const ids = Object.keys(porConductor).sort();
msg.horasTotales = 0;

for (let k = 0; k < ids.length; k++) {
    const id = ids[k];
    const lista = porConductor[id];
    lista.sort(function (a, b) { return a.t - b.t; });


    let inicioSesion = lista[0].t;
    let horas = 0;
    for (let i = 1; i < lista.length; i++) {
        const gap = (lista[i].t - lista[i - 1].t) / 1000;
        if (gap > GAP_S) inicioSesion = lista[i].t;      
        if (gap <= PAUSA_S) horas += gap / 3600;
    }


    const ultimo = lista[lista.length - 1].t;
    const activa = (msg.cfg.ahora - ultimo) <= GAP_S * 1000;
    let tiempoAlVolante = 0;
    if (activa) tiempoAlVolante = (ultimo - inicioSesion) / 3600000;

    const valoresFc = [];
    const valoresSpo2 = [];
    for (let i = 0; i < lista.length; i++) {
        valoresFc.push(lista[i].fc);
        if (!lista[i].movimiento) valoresSpo2.push(lista[i].spo2);
    }

    let totalAlertas = 0, alertasCriticas = 0;
    for (let i = 0; i < msg.alertas.length; i++) {
        if (msg.alertas[i].id !== id) continue;
        totalAlertas++;
        if (msg.alertas[i].critica) alertasCriticas++;
    }

    let vehiculo = id;
    if (id.indexOf("-") > 0) vehiculo = id.split("-")[0];

    const horasRedondeadas = redondear(horas);
    msg.horasTotales += horasRedondeadas;

    msg.filas.conductor.push({
        query: { _id: id },
        payload: { $set: {
            conductor: id,
            vehiculo: vehiculo,
            alertas: totalAlertas,
            alertas_criticas: alertasCriticas,
            fc_prom: promedio(valoresFc),
            spo2_prom: promedio(valoresSpo2),
            horas_conduccion: horasRedondeadas,
            sesion_activa: activa,
            tiempo_al_volante_h: redondear(tiempoAlVolante),
            excede_limite: tiempoAlVolante > LIMITE_H,
            actualizado: new Date(msg.cfg.ahora)
        } }
    });
}

msg.totalConductores = ids.length;
return msg;

// Una sola fila con los totales de la ventana.
let criticas = 0;
for (let i = 0; i < msg.alertas.length; i++) {
    if (msg.alertas[i].critica) criticas++;
}

msg.filas.semana.push({
    query: { _id: "semana" },
    payload: { $set: {
            alertas_total: msg.alertas.length,
        alertas_criticas: criticas,
        horas_conduccion: Math.round(msg.horasTotales * 100) / 100,
        conductores: msg.totalConductores,
        desde: new Date(msg.cfg.desde),
        hasta: new Date(msg.cfg.ahora),
        actualizado: new Date(msg.cfg.ahora)
    } }
});
return msg;

node.status({ fill: "green", shape: "dot", text: msg.totalConductores + " conductores, " + msg.alertas.length + " alertas guardados" });

function armar(lista) {
    const mensajes = [];
    for (let i = 0; i < lista.length; i++) {
        mensajes.push({ query: lista[i].query, payload: lista[i].payload });
    }
    return mensajes;
}

return [armar(msg.filas.diaHora), armar(msg.filas.conductor), armar(msg.filas.semana)];
